"M&E 5th Bảng 3-18 (loãng – đặc); nước thải cống chung ở VN thường ở cận dưới (qua bể phốt, pha loãng nước mưa)": "M&E 5th Table 3-18 (weak – strong); combined-sewer wastewater in VN is usually at the lower end (septic tanks, stormwater dilution)",
