"Tổng hợp số liệu ĐTM/quan trắc các KCN đa ngành; tiêu chuẩn đấu nối thường ≈ QCVN 40:2011 cột B hoặc quy định riêng của KCN": "Compiled EIA/monitoring data of multi-sector IZs; connection standard usually ≈ QCVN 40:2011 column B or IZ-specific rules",
"Nồng độ phụ thuộc cơ cấu ngành và tiêu chuẩn đấu nối của KCN – số liệu vượt tiêu chuẩn đấu nối cho thấy doanh nghiệp chưa tiền xử lý đạt, cần làm rõ trước khi chọn làm số liệu thiết kế.": "Concentrations depend on the industry mix and the IZ connection standard – data above the connection standard indicate inadequate on-site pre-treatment and must be clarified before being adopted as design data.",
"Nước thải y tế (bệnh viện)": "Medical wastewater (hospital)",
"Y tế": "Medical",
"Tổng hợp số liệu quan trắc bệnh viện; quy chuẩn xả QCVN 28:2010/BTNMT": "Compiled hospital monitoring data; discharge regulation QCVN 28:2010/BTNMT",
"Tính chất gần nước thải sinh hoạt; ngoài ra cần khử trùng triệt để và kiểm soát chất thải lây nhiễm, phóng xạ (nếu có). Quy chuẩn xả áp dụng: QCVN 28.": "Similar to domestic wastewater; additionally requires thorough disinfection and control of infectious and radioactive waste (if any). Applicable discharge regulation: QCVN 28.",
"Dệt nhuộm": "Textile dyeing",
"Màu và COD khó phân hủy cao, pH kiềm → thường cần trung hòa, keo tụ/ oxy hóa nâng cao; kiểm tra thêm AOX, kim loại theo QCVN 13-MT.": "High colour and refractory COD, alkaline pH → neutralization, coagulation/advanced oxidation usually needed; also check AOX, metals per QCVN 13-MT.",
"Chế biến thủy sản": "Seafood processing",
"Thủy sản": "Seafood",
"N hữu cơ (protein) và dầu mỡ động thực vật cao → tách mỡ/ tuyển nổi trước sinh học, tải lượng N lớn cần khử nitrat mạnh.": "High organic N (protein) and animal/vegetable fats → fat separation/flotation before biology; high N load needs strong denitrification.",
"Bia – nước giải khát": "Beer – beverages",
"Hữu cơ dễ phân hủy nồng độ cao, pH dao động mạnh (CIP axit/xút) → điều hòa – trung hòa, thường xử lý kỵ khí (UASB/IC) trước hiếu khí; có thể thiếu N.": "High readily biodegradable organics, strongly fluctuating pH (CIP acid/caustic) → equalization – neutralization, usually anaerobic (UASB/IC) before aerobic; may be N-deficient.",
"Chế biến thực phẩm – tinh bột": "Food processing – starch",
"Thực phẩm": "Food",
"WB/IFC EHS Guidelines – Food & Beverage Processing; tài liệu XLNT chế biến tinh bột sắn": "WB/IFC EHS Guidelines – Food & Beverage Processing; cassava starch wastewater literature",
"Nồng độ rất cao, pH axit (tinh bột sắn có CN⁻) → xử lý kỵ khí trước; phần mềm hiện tính theo sơ đồ hiếu khí nên cần giảm tải trước khi áp dụng.": "Very high strength, acidic pH (cassava starch contains CN⁻) → anaerobic pre-treatment; this software sizes an aerobic scheme, so load must be reduced first.",
"Giấy – bột giấy tái chế": "Paper – recycled pulp",
"Giấy": "Paper",
"Thiếu N, P dinh dưỡng (cần bổ sung urê, H₃PO₄), TSS xơ sợi cao, màu (lignin).": "N and P deficient (urea, H₃PO₄ addition needed), high fibrous TSS, colour (lignin).",
"Chăn nuôi heo (sau biogas)": "Pig farming (after biogas)",
"Chăn nuôi": "Livestock",
"Tổng hợp số liệu trang trại heo sau biogas ở VN; QCVN 62-MT:2016/BTNMT": "Compiled data of pig farms after biogas in VN; QCVN 62-MT:2016/BTNMT",
"N rất cao, C/N thấp sau biogas → khử N cần carbon ngoài hoặc công nghệ riêng (Anammox, stripping); kiềm cao.": "Very high N, low C/N after biogas → N removal needs external carbon or dedicated processes (Anammox, stripping); high alkalinity.",
"Cơ khí – xi mạ, điện tử": "Mechanical – electroplating, electronics",
"Xi mạ – điện tử": "Electroplating – electronics",
"Chỉ tiêu quyết định là kim loại nặng, Cr⁶⁺, CN⁻, F⁻ – phải xử lý hóa lý riêng từng dòng (khử Cr⁶⁺, oxy hóa CN⁻, kết tủa) trước khi vào sinh học; phần mềm không tính các chỉ tiêu này.": "Governing parameters are heavy metals, Cr⁶⁺, CN⁻, F⁻ – each stream must be treated physico-chemically (Cr⁶⁺ reduction, CN⁻ oxidation, precipitation) before biology; this software does not model them.",
"nguồn thải nồng độ cao chưa tiền xử lý (công nghiệp, hút bể phốt, nước rỉ rác), mẫu đơn lấy lúc cao điểm": "high-strength sources without pre-treatment (industry, septage, leachate), grab sample at peak hour",
"pha loãng do nước mưa/ nước ngầm thấm vào cống, mẫu lấy sau mưa hoặc giờ thấp điểm": "dilution by stormwater/groundwater infiltration, sample taken after rain or at low-flow hours",
"nguồn hữu cơ dễ phân hủy nồng độ cao (thực phẩm, đồ uống), mẫu đơn lúc cao điểm": "high-strength readily biodegradable sources (food, beverages), grab sample at peak hour",
"pha loãng; hoặc mẫu có chất ức chế (clo dư, kim loại, pH lệch) làm BOD₅ đo thấp giả": "dilution; or sample containing inhibitors (residual chlorine, metals, abnormal pH) giving falsely low BOD₅",
"đất cát theo nước mưa chảy tràn, xả cặn bể/ nạo vét cống, lấy mẫu sát đáy": "soil and sand from stormwater runoff, tank desludging/sewer cleaning, sample taken near the bottom",
"mẫu lấy ở lớp nước trong hoặc sau bể lắng/ bể tự hoại": "sample taken from clear supernatant or after settling/septic tanks",
"nguồn giàu N (bể phốt, chăn nuôi, thủy sản, nước rỉ rác, sản xuất phân bón)": "N-rich sources (septage, livestock, seafood, leachate, fertilizer production)",
"pha loãng; ngành nghèo dinh dưỡng (giấy, dệt, đồ uống)": "dilution; nutrient-poor industries (paper, textile, beverages)",
"nguồn giàu N hữu cơ/ amoni": "sources rich in organic N/ammonium",
"pha loãng; ngành nghèo dinh dưỡng": "dilution; nutrient-poor industries",
"nước thải đã phân hủy lâu (bể phốt, biogas, nước rỉ rác); ghi nhầm NH₄⁺ thay NH₄⁺-N (NH₄⁺ = 1,29 × NH₄-N)": "long-aged wastewater (septic tanks, biogas, leachate); NH₄⁺ reported instead of NH₄⁺-N (NH₄⁺ = 1.29 × NH₄-N)",
"N chủ yếu ở dạng hữu cơ (nước thải tươi, protein) hoặc pha loãng": "N mainly organic (fresh wastewater, protein) or dilution",
"chất tẩy rửa chứa phosphat, thực phẩm/ thủy sản; ghi nhầm PO₄³⁻ thay P (PO₄³⁻ = 3,07 × P)": "phosphate detergents, food/seafood; PO₄³⁻ reported instead of P (PO₄³⁻ = 3.07 × P)",
"pha loãng; ngành nghèo P (giấy, dệt); chỉ đo PO₄³⁻ hòa tan thay vì tổng P": "dilution; P-poor industries (paper, textile); only dissolved PO₄³⁻ measured instead of total P",
"xưởng cơ khí, gara, trạm xăng dầu, bếp ăn chưa có bể tách dầu mỡ": "mechanical workshops, garages, petrol stations, canteens without grease traps",
"nguồn dệt nhuộm, giấy, mực in, chế biến gỗ": "textile dyeing, paper, printing ink, wood processing sources",
"nguồn kiềm (dệt nhuộm – NaOH, Na₂CO₃; chăn nuôi – NH₄HCO₃)": "alkaline sources (textile – NaOH, Na₂CO₃; livestock – NH₄HCO₃)",
