"Đặt khe lưới tinh 1 mm.": "Set fine screen aperture to 1 mm.",
"Giảm phân suất nạp V_F/V_T.": "Reduce fill fraction V_F/V_T.",
"Tăng số bể SBR.": "Increase the number of SBR tanks.",
"Bố trí bể điều hòa.": "Provide an equalization tank.",
"Tăng chiều sâu nước ≥ chiều cao module + 0,8 m.": "Increase water depth to ≥ module height + 0.8 m.",
"Đưa tỷ lệ chiếm chỗ module về khoảng khuyến cáo.": "Bring module occupancy back into the recommended range.",
"Tăng SRT thiết kế (tăng thể tích & số module).": "Increase design SRT (more volume & modules).",
"Tăng tỷ lệ chiếm chỗ module φ.": "Increase module occupancy φ.",
"Bộ tỷ lệ đặc trưng không nhất quán – giảm sCOD/COD hoặc tăng bCOD/BOD theo số liệu phân tích.": "Characteristic ratios inconsistent – reduce sCOD/COD or increase bCOD/BOD per laboratory data.",
"Nâng cao độ đáy bể sinh học 0,5 m.": "Raise the bioreactor floor by 0.5 m.",
"Hoặc bố trí trạm bơm nước sau xử lý ra nguồn tiếp nhận.": "Or provide an effluent pump station to the receiving water.",
"Đổi cỡ ống (DN) tuyến tương ứng ở tab Thủy lực.": "Change the pipe size (DN) of that line in the Hydraulics tab.",
"Phần mềm đã tính liều NaOH bổ sung (xem bảng hóa chất). Hoặc tăng khử nitrat để hoàn trả kiềm.": "The software has calculated the NaOH dose (see chemical table). Alternatively increase denitrification to recover alkalinity.",
"Tăng hệ số tăng tải TSS do nước tách bùn ở bảng hiệu suất.": "Increase the TSS load factor from sludge liquors in the efficiency table.",
"Điều chỉnh thời gian lưu bể gom về 12 phút.": "Set sump retention time to 12 min.",
"Điều chỉnh chiều rộng/chiều sâu bể lắng cát.": "Adjust grit chamber width/depth.",
"CAS với SRT dài vận hành như sục khí kéo dài – chấp nhận được; hoặc giảm SRT nếu không cần nitrat hóa.": "CAS with long SRT operates as extended aeration – acceptable; or reduce SRT if nitrification is not needed.",
"Tăng vận tốc dòng vòng.": "Increase loop velocity.",
"Đây là nhận xét đặc trưng nước thải – phần mềm đã xử lý bằng carbon ngoài / khử P hóa học tự động nếu bật.": "This is a wastewater characteristic remark – handled by automatic external carbon / chemical P removal if enabled.",
