"giảm tải hữu cơ nhưng lấy mất carbon cho khử nitrat – phần mềm tự kiểm tra và bổ sung carbon ngoài nếu chọn \"Tự động\".": "reduces organic load but removes carbon for denitrification – the software checks and adds external carbon when \"Automatic\" is selected.",
