"Q 5.678,1 m³/ngđ; BOD 160; TSS 180; TKN 35; MLSS 2.100; SRT 12 ngày; T 10 °C; α 0,5; β 1,0; F 0,8; SOTE 0,20; ngập đĩa 3,66 m; η máy thổi 0,70. Kết quả bảng tính: V 1.699 m³, HRT ≈ 7 h, nhu cầu O₂ 77 kg/h (khử BOD + nitrat hóa). COD, NH₄, TP, kiềm giả định. SRT 12 ngày của bảng tính không đủ cho nitrat hóa ở 10 °C theo M&E (SRT yêu cầu ≈ 20 ngày) – phần mềm báo KHÔNG ĐẠT.": "Q 5,678.1 m³/d; BOD 160; TSS 180; TKN 35; MLSS 2,100; SRT 12 d; T 10 °C; α 0.5; β 1.0; F 0.8; SOTE 0.20; diffuser submergence 3.66 m; blower η 0.70. Spreadsheet results: V 1,699 m³, HRT ≈ 7 h, O₂ demand 77 kg/h (BOD removal + nitrification). COD, NH₄, TP, alkalinity assumed. The spreadsheet SRT of 12 d is insufficient for nitrification at 10 °C per M&E (required SRT ≈ 20 d) – the software reports NOT MET.",
