"TRÍCH DẪN CHI TIẾT TÀI LIỆU THAM CHIẾU": "DETAILED CITATIONS OF REFERENCES",
"Bảng, phương trình, ví dụ, mục và tài liệu nhà cung cấp được nhắc tới trong cột \"Công thức / cơ sở lựa chọn\", \"Nguồn\" và ghi chú của bản tính: vị trí trong tài liệu, biểu thức, giá trị bảng và các dòng tính sử dụng. Nội dung là tóm tắt / số liệu trích theo tài liệu – khi phát hành chính thức đối chiếu với bản gốc.": "Tables, equations, examples, sections and supplier documents cited in the \"Formula / basis\", \"Source\" columns and notes of the calculation: location in the document, expression, table values and the calculation rows using them. Content is a summary / data extracted from the documents – check against the originals for formal issue.",
