"Nhập kết quả quan trắc nước ra thực tế vào cột \"Đo thực tế\" để đối chiếu mô hình: lệch > 30 % thì cần hiệu chỉnh các tỷ lệ đặc trưng nước thải (tab 4), SVI, SOTE/α hoặc kiểm tra số liệu vận hành.": "Enter measured effluent results in the \"Measured\" column to check the model: a deviation > 30 % means the wastewater fractions (tab 4), SVI, SOTE/α need calibration or the operating data should be checked.",
