"vòng) với mục tiêu ≤ 90 % giới hạn xả. Thứ tự ưu tiên: đủ oxy (DO) → độ kiềm → tuổi bùn (MLSS, thời gian sục khí) → tuần hoàn nội / pha thiếu khí → carbon ngoài → hóa chất khử P → kiểm soát bùn lắng → khử trùng. Thay đổi MLSS cần thực hiện từ từ (giảm xả bùn trong 1 – 2 SRT) và theo dõi SVI, DO, NH₄-N.": "rounds) targeting ≤ 90 % of the discharge limit. Priority: sufficient oxygen (DO) → alkalinity → sludge age (MLSS, aeration time) → internal recycle / anoxic phase → external carbon → P-removal chemicals → settling control → disinfection. Change MLSS gradually (reduce wasting over 1 – 2 SRT) and monitor SVI, DO, NH₄-N.",
"Chẩn đoán quá trình": "Process diagnosis",
"Hiện tại": "Current",
"Sau khuyến cáo": "After recommendations",
"Tiêu chí": "Criterion",
"Hóa chất & điện cấp khí": "Chemicals & aeration power",
"Hiện tại (kg hoặc kWh/ngđ)": "Current (kg or kWh/d)",
"Chi phí hiện tại (nghìn đ/ngđ)": "Current cost (thousand VND/d)",
"Đơn giá theo tab 4 (nhóm chi phí). Điện cấp khí tính theo lượng khí cần để giữ DO đặt (PT 5-77), không vượt lưu lượng khí cấp.": "Unit prices per tab 4 (cost group). Aeration power is based on the air needed to hold the DO setpoint (Eq. 5-77), not exceeding the air supplied.",
"Cơ sở tính & giới hạn của mô hình": "Calculation basis & model limitations",
"Trạng thái ổn định theo M&E 5th: SRT giải từ khối bùn đang giữ M = MLSS·V = P_X,TSS·SRT (PT 8-20, 8-21); cơ chất còn lại PT (7-46); NH₄-N ra giải ngược PT (7-94) với SRT hiếu khí và DO thực đạt; NOx PT (8-24); nhu cầu oxy PT (8-23).": "Steady state per M&E 5th: SRT solved from the sludge mass held M = MLSS·V = P_X,TSS·SRT (Eq. 8-20, 8-21); residual substrate Eq. (7-46); effluent NH₄-N by inverting Eq. (7-94) with aerobic SRT and achieved DO; NOx Eq. (8-24); oxygen demand Eq. (8-23).",
"DO thực đạt tính từ khả năng truyền oxy của hệ cấp khí ở nhiệt độ nước cao nhất theo PT (5-70); động học nitrat hóa tính ở nhiệt độ thấp nhất – tổ hợp bất lợi.": "Achieved DO from the oxygen transfer capacity of the aeration system at maximum water temperature per Eq. (5-70); nitrification kinetics at minimum temperature – a conservative combination.",
"Khử nitrat: SDNR theo F/M_b (PT 8-56 – 8-58, Bảng 8-22), giới hạn bởi lượng nitrat được đưa về vùng thiếu khí (PT 8-61) và carbon nội tại; methanol theo Bảng 8-26 (4,98 g COD/g N).": "Denitrification: SDNR from F/M_b (Eq. 8-56 – 8-58, Table 8-22), limited by the nitrate delivered to the anoxic zone (Eq. 8-61) and internal carbon; methanol per Table 8-26 (4.98 g COD/g N).",
"Photpho: đồng hóa f_P·P_X,VSS; EBPR theo rbCOD:P (Bảng 8-30) trừ rbCOD bị nitrat tuần hoàn tiêu thụ; khử P hóa học theo tỷ lệ mol Al:P (mục 6-4).": "Phosphorus: assimilation f_P·P_X,VSS; EBPR from rbCOD:P (Table 8-30) less rbCOD consumed by recycled nitrate; chemical P removal by Al:P molar ratio (section 6-4).",
"TSS ra: giá trị cơ sở (tab 4) hiệu chỉnh theo chỉ số quá tải bể lắng (Bảng 8-34: SOR, SLR, R cần theo SVI) hoặc tỷ lệ gạn cho phép (PT 8-50) – quan hệ kinh nghiệm, nên hiệu chỉnh theo số liệu đo.": "Effluent TSS: base value (tab 4) adjusted by the clarifier overload index (Table 8-34: SOR, SLR, required R from SVI) or the allowable decant ratio (Eq. 8-50) – an empirical relation; calibrate with measured data.",
"Coliform: liều clo kết hợp theo Bảng 12-14 (tiếp xúc 30 phút). Kết quả là ước tính kỹ thuật phục vụ vận hành – cần xác nhận bằng quan trắc và thí nghiệm (Jartest, SDNR, OUR).": "Coliform: combined chlorine dose per Table 12-14 (30 min contact). Results are engineering estimates for operation – confirm by monitoring and tests (jar test, SDNR, OUR).",
