"Nitrat tạo ra trong pha sục khí cuối bị gạn theo nước ra: giảm chiều sâu gạn mỗi chu kỳ (tăng số chu kỳ/ngày) và kết thúc pha phản ứng bằng khuấy thiếu khí trước khi lắng": "Nitrate formed in the last aerated phase leaves with the decant: reduce the decant depth per cycle (more cycles/day) and end the react phase with anoxic mixing before settling",
"Tỷ lệ gạn đã thấp: kết thúc mỗi pha phản ứng bằng khuấy thiếu khí 20 – 30 phút (có thể châm carbon) trước pha lắng.": "Decant ratio already low: end each react phase with 20 – 30 min anoxic mixing (carbon dosing possible) before settling.",
