"): bổ sung bể lắng hoặc lọc bậc 3 (lọc đĩa vải), kiểm soát SVI (selector, clo hóa bùn tuần hoàn).": "): add clarifier area or tertiary filtration (cloth disc), control SVI (selector, RAS chlorination).",
