"Mô hình trạng thái ổn định M&E 5th: SRT giải từ khối bùn đang giữ (PT 8-20, 8-21), NH₄-N theo PT (7-94) với DO thực đạt theo PT (5-70), khử nitrat SDNR (PT 8-56 – 8-58, Bảng 8-22), P theo VD 8-13, Bảng 8-30, mục 6-4; TSS theo Bảng 8-34 / PT (8-50); clo theo Bảng 12-14. Giá trị là kết quả tính tại thời điểm xuất (không phải công thức sống).": "M&E 5th steady-state model: SRT solved from the sludge mass held (Eq. 8-20, 8-21), NH₄-N per Eq. (7-94) with achieved DO per Eq. (5-70), denitrification SDNR (Eq. 8-56 – 8-58, Table 8-22), P per Ex. 8-13, Table 8-30, section 6-4; TSS per Table 8-34 / Eq. (8-50); chlorine per Table 12-14. Values are results at export time (not live formulas).",
"HIỆU CHỈNH ĐẶC TRƯNG NƯỚC THẢI & HẰNG SỐ ĐỘNG HỌC THEO SỐ LIỆU ĐO THỰC TẾ": "CALIBRATION OF WASTEWATER CHARACTERISTICS & KINETIC CONSTANTS FROM MEASURED DATA",
"Nội suy ngược: mỗi chỉ tiêu đo hiệu chỉnh một thông số nhạy nhất (chia đôi, lặp 3 lượt). TSS → TSS ra cơ sở; bùn dư → b_H; NH₄-N → μmax,AOB; NO₃-N/TN → rbCOD/bCOD và SDNR₂₀; TP → f_P / rbCOD:P / Al:P; COD → sCOD/COD; BOD → gBOD/gTSS; Coliform → coliform sau sinh học.": "Back-calculation: each measured parameter calibrates its most sensitive constant (bisection, 3 passes). TSS → base effluent TSS; excess sludge → b_H; NH₄-N → μmax,AOB; NO₃-N/TN → rbCOD/bCOD and SDNR₂₀; TP → f_P / rbCOD:P / Al:P; COD → sCOD/COD; BOD → gBOD/gTSS; Coliform → coliform after biology.",
