"Hiệu chỉnh đặc trưng nước thải & hằng số động học theo số liệu đo thực tế": "Calibrate wastewater characteristics & kinetic constants from measured data",
"Khi số đo nước ra (cột \"Đo thực tế\" ở bảng trên) lệch so với dự đoán, phần mềm nội suy ngược các đặc trưng nước thải và hằng số động học sao cho mô hình tái lập đúng số đo, trong điều kiện lúc lấy mẫu. Bấm \"Áp dụng\" để thay các giá trị này vào thông số thiết kế (tab 4) – mọi phương án thiết kế và phần kiểm tra vận hành tự tính lại.": "When measured effluent values (the \"Measured\" column above) deviate from the prediction, the software back-calculates the wastewater characteristics and kinetic constants so that the model reproduces the measurements under the sampling conditions. Press \"Apply\" to put these values into the design parameters (tab 4) – all design alternatives and the operations check are recalculated.",
"Nhiệt độ nước lúc lấy mẫu (°C)": "Water temperature at sampling (°C)",
"trống = nhiệt độ thấp nhất": "blank = minimum temperature",
