"trống = tính theo máy thổi": "blank = computed from blowers",
"Bùn dư thực tế (kg DS/ngđ)": "Measured excess sludge (kg DS/d)",
"từ nhật ký xả bùn – hiệu chỉnh b_H": "from sludge wasting log – calibrates b_H",
"Chưa có số đo – nhập ít nhất một chỉ tiêu nước ra ở cột \"Đo thực tế\" hoặc lượng bùn dư thực tế.": "No measurements – enter at least one effluent parameter in the \"Measured\" column or the measured excess sludge.",
"Đối chiếu số đo – mô hình (điều kiện lấy mẫu: T =": "Measured vs model (sampling conditions: T =",
"Lệch": "Deviation",
"Thông số hiệu chỉnh (nội suy ngược)": "Calibrated parameters (back-calculated)",
"Thay đổi": "Change",
"Mỗi chỉ tiêu đo hiệu chỉnh một thông số nhạy nhất (giải ngược một chiều, lặp 3 lượt vì các thông số tương tác): TSS → TSS ra cơ sở; bùn dư → b_H; NH₄-N → μmax,AOB (Bảng 8-14); NO₃-N hoặc TN → rbCOD/bCOD (SDNR theo Bảng 8-22) và SDNR₂₀ của công nghệ; TP → f_P, rbCOD:P hoặc Al:P theo cơ chế khử P; COD → sCOD/COD (COD trơ hòa tan); BOD → gBOD/gTSS; Coliform → coliform sau sinh học. Nên dùng số liệu trung bình nhiều ngày ở chế độ ổn định; \"Chạm biên\" cho thấy sai lệch do nguyên nhân khác (số liệu vận hành, thiết bị) cần kiểm tra lại.": "Each measured parameter calibrates its most sensitive constant (one-dimensional back-calculation, 3 passes because the constants interact): TSS → base effluent TSS; excess sludge → b_H; NH₄-N → μmax,AOB (Table 8-14); NO₃-N or TN → rbCOD/bCOD (SDNR per Table 8-22) and the process SDNR₂₀; TP → f_P, rbCOD:P or Al:P by P-removal mechanism; COD → sCOD/COD (refractory soluble COD); BOD → gBOD/gTSS; Coliform → coliform after biology. Use multi-day averages at steady operation; \"At bound\" indicates the deviation has other causes (operating data, equipment) to be checked.",
"Áp dụng các thông số hiệu chỉnh vào thông số thiết kế (tab 4)? Các phương án thiết kế sẽ được tính lại.": "Apply the calibrated parameters to the design parameters (tab 4)? The design alternatives will be recalculated.",
