"Tái lập Preliminary Study của Kubota: 700 m³/ngđ (lưu lượng ổn định qua bể điều hòa), BOD 750, T-N 100 mg/L, nhiệt độ thấp nhất 20 °C; EK400 × 6 (2 bể × 3), F = 0,40 m³/m²·ngđ, MLSS bể màng 15.000 mg/L, tuần hoàn 3Q. Kết quả tài liệu: 2.400 tấm (1.920 m²), bể thiếu khí yêu cầu 120,6 m³, bể màng 2 × (4,0 × 4,5 × 4,2 m) = 151,2 m³, bể tiền sục khí yêu cầu 163,8 m³; O₂: khử BOD 262,5 + nitrat hóa 248,0 + nội bào 424,0 = 934,5 kg/ngđ; khí rửa màng 16,8 m³/phút cấp 241,2 kg O₂/ngđ, đĩa bọt mịn 29,0 m³/phút. T_max không có trong tài liệu (giả định 30 °C).": "Reproduction of the Kubota Preliminary Study: 700 m³/d (flow equalized), BOD 750, T-N 100 mg/L, minimum temperature 20 °C; EK400 × 6 (2 tanks × 3), F = 0.40 m³/m²·d, membrane tank MLSS 15,000 mg/L, recycle 3Q. Document results: 2,400 cartridges (1,920 m²), required anoxic tank 120.6 m³, membrane tanks 2 × (4.0 × 4.5 × 4.2 m) = 151.2 m³, required pre-aeration tank 163.8 m³; O₂: BOD 262.5 + nitrification 248.0 + endogenous 424.0 = 934.5 kg/d; membrane scour air 16.8 m³/min supplying 241.2 kg O₂/d, fine-bubble air 29.0 m³/min. T_max not given in the document (30 °C assumed).",
